 def task(lang):
  de=lang=='De'
  head=('**Praktikumsaufgabe – vollständige Durchführung und Auswertung**\n\nFühre den angegebenen Versuch ausschließlich im betreuten Schulversuch nach dem geltenden Sicherheitsplan durch. Lege ein eigenes vollständiges Durchführungs- und Beobachtungsprotokoll vor. Die bereitgestellte synthetische Reihe dient als Auswertungsbeispiel; sie ersetzt keine tatsächlich beobachtbare praktische Durchführung. Ist diese nicht überprüfbar, bleibt der praktische Teil offen.\n\n' if de else '**Practical assessment – complete execution and evaluation**\n\nPerform the specified activity only in the supervised school setting under the applicable safety procedure. Submit your own complete execution and observation record. The supplied synthetic series is an evaluation example; it does not replace verifiable practical execution. If execution cannot be verified, the practical part remains open.\n\n')
  head+=('**Material und festgelegte Bedingungen:**\n\n' if de else '**Materials and specified conditions:**\n\n')+x['material'+lang]+'\n\n'
  head+=('**Vorgegebener Ablauf:**\n\n' if de else '**Specified procedure:**\n\n')+'\n'.join(str(j+1)+'. '+v for j,v in enumerate(x['procedure'+lang]))+'\n\n'
  head+=('**Synthetische Vergleichsreihe (keine Lernendenmessung):**\n\n' if de else '**Synthetic comparison series (not learner measurements):**\n\n')+'```json\n'+json.dumps(x['syntheticData'],ensure_ascii=False,indent=2)+'\n```\n\n'
  head+=('**Aufgaben:**\n\n1. Führe den vollständigen vorgegebenen Ablauf sicher und regelgetreu durch. Dokumentiere unmittelbar deine eigenen Mengen/Messwerte, Bedingungen und Beobachtungen sowie die tatsächlich überprüfbaren Handlungen. (4 BE)\n2. ' if de else '**Tasks:**\n\n1. Execute the complete specified procedure safely and according to its rules. Immediately record your own amounts/readings, conditions and observations, and the actions that can actually be verified. (4 points)\n2. ')+x['taskDemand'+lang]+(' (4 BE)\n3. ' if de else ' (4 points)\n3. ')+x['freshTransferTask'+lang]+(' (2 BE)' if de else ' (2 points)')
  return head
 def solution(lang):
  de=lang=='De'
