  text+=('**Ausgearbeitetes synthetisches Auswertungsbeispiel:**\n\n' if de else '**Worked synthetic evaluation example:**\n\n')+x['modelAnswer'+lang]+'\n\n'
  text+=('**Unabhängiger Transfer:**\n\n' if de else '**Independent transfer:**\n\n')+x['freshTransferAnswer'+lang]+'\n\n'
  text+=('**Rubrik (je 2 BE; Bestehen nur bei allen 10 BE):**\n\n' if de else '**Rubric (2 points each; all 10 points required to pass):**\n\n')+'\n'.join('- '+v for v in x['scoring'+lang])
  return text
